describe('Async Operation Cancellation with Abort Button', () => {
  beforeEach(() => {
    cy.visit('/async-operation');
  });

  it('should cancel an ongoing async operation when Abort button is clicked', () => {
    // Intercept the API call
    cy.intercept('GET', '/api/async-operation/start').as('startOperation');
    cy.intercept('GET', '/api/async-operation/cancel').as('cancelOperation');

    // Click the start button to initiate the async operation
    cy.get('[data-testid="start-async-btn"]').click();
    cy.wait('@startOperation');

    // Verify the operation is in progress
    cy.get('[data-testid="operation-status"]').should('contain', 'In Progress');

    // Click the Abort button
    cy.get('[data-testid="abort-btn"]').click();

    // Verify the cancel button was clicked
    cy.get('[data-testid="abort-btn"]').should('be.visible');

    // Verify the operation was cancelled
    cy.wait('@cancelOperation');
    cy.get('[data-testid="operation-status"]').should('contain', 'Cancelled');

    // Verify the cancel button is no longer visible
    cy.get('[data-testid="abort-btn"]').should('not.exist');
  });

  it('should not cancel an already completed async operation', () => {
    // Intercept the API call
    cy.intercept('GET', '/api/async-operation/start').as('startOperation');
    cy.intercept('GET', '/api/async-operation/cancel').as('cancelOperation');

    // Click the start button to initiate the async operation
    cy.get('[data-testid="start-async-btn"]').click();
    cy.wait('@startOperation');

    // Verify the operation is in progress
    cy.get('[data-testid="operation-status"]').should('contain', 'In Progress');

    // Wait for the operation to complete
    cy.wait('@startOperation').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify the operation is completed
    cy.get('[data-testid="operation-status"]').should('contain', 'Completed');

    // Click the Abort button
    cy.get('[data-testid="abort-btn"]').click();

    // Verify the operation was not cancelled (already completed)
    cy.get('[data-testid="operation-status"]').should('contain', 'Completed');

    // Verify the cancel button is still visible
    cy.get('[data-testid="abort-btn"]').should('be.visible');
  });
});
